content.text:
{
 "批": "N14",
 "裁定": [
  {
   "编号": "T188-c2",
   "项": "C1",
   "裁定": "是",
   "依据": "这些武官星呢",
   "理由": "原文先说出杀破狼是「武官星」这一人物之象，紧接着由此说它们最喜逢火铃，合于C1「先说出这颗星是什么人物再推出结论」；且两人在T188-c1已一致将「武官星」判为象名，依codebook名目含人物字者取象，故记C1。"
  },
  {
   "编号": "T188-c2",
   "项": "C2",
   "裁定": "否",
   "依据": "",
   "理由": "「武官星」是以人物身份（武官）作名目，按codebook拿不准时含人、物字者归象而不归义，同一理由不重复记为C2。"
  },
  {
   "编号": "T188-c3",
   "项": "C1",
   "裁定": "是",
   "依据": "这些武官星呢",
   "理由": "同T188-c2，原文以「武官星」这一人物之象为由说最喜火铃，记C1。"
  },
  {
   "编号": "T188-c3",
   "项": "C2",
   "裁定": "否",
   "依据": "",
   "理由": "同T188-c2，「武官星」为象名而非抽象性质，不记C2。"
  },
  {
   "编号": "T223-c4",
   "项": "C5",
   "裁定": "否",
   "依据": "",
   "理由": "前文「非常厚道、谦和、温和」是在描述天相星本身的性质（两人已一致记为C2），原文并未说出由这些性情按人情推出配偶好的因果关系，中间无「所以」之类连接，不足以记C5。"
  },
  {
   "编号": "T530-c1",
   "项": "C1",
   "裁定": "否",
   "依据": "",
   "理由": "「走子女宫」是说行运走到子女宫，属C4所列「行运走到哪一宫」，子女宫所主即子女是宫位本来的职掌，不是借宫名字面作比喻说理（如「地空嘛空就是空掉了」），故不记C1。"
  },
  {
   "编号": "T877-c2",
   "项": "C3",
   "裁定": "否",
   "依据": "",
   "理由": "原文只说廉贞七杀在福德就是屠夫，「在福德」是条件所在的宫位而非说出位置关系在起作用，与codebook反例「红鸾坐命的女孩子脑筋清楚（只说有星在命宫）」同类，按直断不记C3。"
  }
 ]
}

{
 "批": "Q07",
 "裁定": [
  {
   "编号": "qs-1-18-2:s002#1",
   "项": "问B",
   "裁定": "义名",
   "依据": "",
   "理由": "名目的实质内容是「主祸福」，即星所主之事与吉凶，正合义名定义；「神」在此只是如「星」一类的泛称后缀，并非一个想得出样子的具体人物或物象，不足以触发「有人物字即象名」的兜底规则。"
  },
  {
   "编号": "qs-2-3-11:s001#2",
   "项": "C2",
   "裁定": "是",
   "依据": "见杀",
   "理由": "「杀」不是列举具体星名，而是以性质、类别称呼一类星并以此为由断兄弟全无，与本批两人已一致判为C2的「加吉星灾少」同例，应作义。"
  },
  {
   "编号": "qs-2-5-19:s001#4",
   "项": "C5",
   "裁定": "否",
   "依据": "",
   "理由": "本条条件原文是「见羊陀火铃空劫」，「必克」与「宜偏室生」是对同一星组并列作出的两个判断，原文无「故」「所以」等字把必克当作宜偏室生的理由，按只有星组即有结论作直断。"
  },
  {
   "编号": "qs-1-47-31:s001#2",
   "项": "C2",
   "裁定": "是",
   "依据": "杀不加",
   "理由": "「杀」同样是以性质、类别称一类星，原文以不加此类星为由断声名远播，与「加吉星」「见杀」同例处理为义。"
  },
  {
   "编号": "qs-3-20-98:s001#1",
   "项": "C1",
   "裁定": "否",
   "依据": "",
   "理由": "C1要求原文借星名字面意思来说明结论，这里只并列星名与「文正兼备」，再举孙膑为例，并未说出以文昌之文、武曲之武为由，乙自己也承认原文未明说，故不计象。"
  },
  {
   "编号": "qs-3-20-265:s002#1",
   "项": "C3",
   "裁定": "否",
   "依据": "",
   "理由": "本句新增的理由只有「岁限行到」，codebook把「行运走到哪一宫」整个归为C4时机；劫空相夹的位置关系是前句「劫空夹命为败局」已定的格局，本句未再把它当理由说出，故只记时不记位。"
  }
 ]
}

{
 "批": "N07",
 "裁定": [
  {
   "编号": "T183-c1",
   "项": "C4",
   "裁定": "是",
   "依据": "开始进入这种贪狼文昌",
   "理由": "此条适用大限，原文「开始进入」明说是行运走到贪狼文昌所在之宫才有此断，属 codebook C4「行运走到哪一宫」，与本批 T362「一进来的时候」两人同判 C4 为是的处理一致。"
  },
  {
   "编号": "T183-c1",
   "项": "问D",
   "裁定": "是",
   "依据": "",
   "理由": "原文在「很辛苦」之后不止一句「因为他有前科」，还接着说「他没有办法」「也会有记录啊」，把前科如何令人没有出路、从而辛苦说开了一层，超出「某某所以怎样」的直陈。"
  },
  {
   "编号": "T183-c2",
   "项": "C4",
   "裁定": "是",
   "依据": "开始进入这种贪狼文昌",
   "理由": "同 T183-c1：「开始进入」是说大限行到此宫，原文把时机当作得出「孤单」的条件，按 C4 答是。"
  },
  {
   "编号": "T183-c2",
   "项": "问D",
   "裁定": "是",
   "依据": "",
   "理由": "同 T183-c1：「他没有办法…因为他有前科…也会有记录啊」在前科这一人情理由之外又多了一层说明，故问D 答是。"
  },
  {
   "编号": "T203-c1",
   "项": "C4",
   "裁定": "是",
   "依据": "在读书这段时间中间呢逢到巨门",
   "理由": "原文「巨门星进来的时候，在读书这段时间中间呢逢到巨门」明说是大限行到读书这段时间逢到巨门才断是非，属 C4 行运走到；至于「不管入庙还是落陷」只排除亮度（C3），不影响时机。"
  },
  {
   "编号": "T203-c2",
   "项": "C2",
   "裁定": "否",
   "依据": "",
   "理由": "「交友不慎」不是「是非很多」这一类的成员、实例或同义说法，而是由是非多推出的人事缘由，不属 C2 的类属关系。"
  },
  {
   "编号": "T203-c2",
   "项": "C5",
   "裁定": "是",
   "依据": "都代表是非很多，所以他在读国中高中的这段时间，交友一定不慎",
   "理由": "由「是非很多」用「所以」推出「交友一定不慎」，是按人情事理由后果反推其做法（交友不慎才致是非），codebook C5 明说因果两个方向都算。"
  },
  {
   "编号": "T315-c3",
   "项": "C4",
   "裁定": "是",
   "依据": "杀星进来的时候",
   "理由": "此条适用流年，原文「杀星进来的时候」说的是流年杀星行入才论度过与否，属 C4 行运走到，与 T362「一进来的时候」两人同判为是一致；亮度另记 C3。"
  },
  {
   "编号": "T483-c1",
   "项": "C4",
   "裁定": "否",
   "依据": "",
   "理由": "原文「然后呢这个44岁又再婚」只是叙述命例在何岁发生再婚，既未说盘面，也未说年岁或行运如何起作用，44岁是事件的时间点而非理由，按直断处理。"
  },
  {
   "编号": "T1417-c1",
   "项": "C4",
   "裁定": "否",
   "依据": "",
   "理由": "此步结论「不杀」由「因为太太…小得很多」这一人情理由推出（C5），「再逢到这」所指不明，原文也没有把它当作得出不杀的理由，只是本来会杀的情境，故不计 C4。"
  },
  {
   "编号": "T1519-c2",
   "项": "问D",
   "裁定": "否",
   "依据": "",
   "理由": "原文「杀星不亮就是你根本没有预警，叫做吉处藏凶」是把不亮、没有预警、吉处藏凶三者并列改称，没有再多一句解释为何不亮便是吉处藏凶；与 T315-c1 另有「看起来外面是好事，实际上是杀凶事在里面」那样的解释句不同。"
  }
 ]
}

{
 "批": "N36",
 "裁定": [
  {
   "编号": "T114-c1",
   "项": "C1",
   "裁定": "否",
   "依据": "",
   "理由": "「武官带→带兵打仗」是以武官这一类别的本来职事推出结论，属 C2（codebook 反例「将星的人适合当武官」即归 C2），原文并未借形象、比喻说明，故 C1 不计。"
  },
  {
   "编号": "T114-c2",
   "项": "C1",
   "裁定": "否",
   "依据": "",
   "理由": "同 T114-c1，「到边疆去打仗」是武官一类的职事，原文只以类别推出，未另借形象，归 C2 不归 C1。"
  },
  {
   "编号": "T355-c1",
   "项": "C2",
   "裁定": "否",
   "依据": "",
   "理由": "「喜神」只是对天喜的称呼，原文把它当理由的是「逢到化忌」「男命」等条件，并未说出喜神的性质为何导致夫妻生离死别，故 C2 不计。"
  },
  {
   "编号": "T439-c1",
   "项": "问D",
   "裁定": "否",
   "依据": "",
   "理由": "「这个忌我们意思就是说有凶星在兄弟宫」只是把化忌译成凶星（已计入 C2），之后直接列解释，没有再说凶星为何带来兄弟不和，故问D为否。"
  },
  {
   "编号": "T439-c2",
   "项": "问D",
   "裁定": "否",
   "依据": "",
   "理由": "同 T439-c1，原文只说有凶星就有兄弟夭折，未再解释为什么。"
  },
  {
   "编号": "T439-c3",
   "项": "问D",
   "裁定": "否",
   "依据": "",
   "理由": "同 T439-c1，原文只说有凶星就有合伙破财，未再解释为什么。"
  },
  {
   "编号": "T648-c1",
   "项": "C1",
   "裁定": "是",
   "依据": "田宅宫就被贴在法院民事厅上",
   "理由": "原文借「田宅宫被贴在法院民事厅上」的景象，并取田宅宫名的字面之义（房产）来说明为何被拍卖，属借形象与宫名字面推结论。"
  },
  {
   "编号": "T648-c1",
   "项": "C5",
   "裁定": "否",
   "依据": "",
   "理由": "「贴在法院民事厅上」是对结果的形象描述，原文没有说出官司与拍卖之间的人情事理因果，故 C5 不计。"
  },
  {
   "编号": "T648-c1",
   "项": "问D",
   "裁定": "否",
   "依据": "",
   "理由": "原文除「官司是非的星」与这一形象说法外，没有再加一句解释为什么会被拍卖，故问D为否。"
  },
  {
   "编号": "T910-c1",
   "项": "C5",
   "裁定": "否",
   "依据": "",
   "理由": "原文只说「90岁100岁以后才有科，就代表说……死了以后才有名」，由年岁到「死后」的常理推断未在原文说出，依据只是时机（C4），故 C5 不计。"
  },
  {
   "编号": "T1105-c3",
   "项": "C3",
   "裁定": "否",
   "依据": "",
   "理由": "原文只说「在疾厄宫……当然是左脚子我们都知道」，疾厄宫只是条件所在，宫位与左脚的对应关系原文并未说出，近于 codebook C3 反例，按直断处理。"
  }
 ]
}

{
 "批": "N27",
 "裁定": [
  {
   "编号": "T95-c2",
   "项": "C1",
   "裁定": "是",
   "依据": "男人拿武官星最好",
   "理由": "前提是「将星／武官星」这一人物形象，原文由「武官」这个人物直接推出男人拿到最好，属先说出星是什么人物再由人物推结论。"
  },
  {
   "编号": "T95-c2",
   "项": "C2",
   "裁定": "否",
   "依据": "",
   "理由": "「男人最好」不是「将／武官」这一类的成员、实例或本来特征，与说明中「将星的人适合当武官」归C2的情形不同。"
  },
  {
   "编号": "T95-c2",
   "项": "C5",
   "裁定": "否",
   "依据": "",
   "理由": "原文只说「男人拿武官星最好」，没有说出身份、处境与得失之间的人情事理，推不出C5。"
  },
  {
   "编号": "T95-c3",
   "项": "C1",
   "裁定": "否",
   "依据": "",
   "理由": "武官星→化将是类与实例的关系，按说明「将星的人适合当武官（见C2）」只归C2，原文没有另借形象说明。"
  },
  {
   "编号": "T237-c2",
   "项": "C1",
   "裁定": "否",
   "依据": "",
   "理由": "将星→干将军与说明中「将星的人适合当武官」同型，是类的实例，归C2而非借形象推理。"
  },
  {
   "编号": "T237-c2",
   "项": "C3",
   "裁定": "否",
   "依据": "",
   "理由": "「化权化将干将军」里的化权是与化将连说的结果描述，原文没有把化权当作推出干将军的条件；七杀在午的位置是c1那一步的依据。"
  },
  {
   "编号": "T705-c1",
   "项": "C3",
   "裁定": "否",
   "依据": "",
   "理由": "原文只说某星落在父母宫就代表离散，与说明反例「红鸾坐命（只说有星在命宫）」同型，没有说出宫位关系在起作用。"
  },
  {
   "编号": "T762-c1",
   "项": "C2",
   "裁定": "否",
   "依据": "",
   "理由": "「带杀」就是「本宫有杀星」这个条件本身，原文没有点出具体星再说其性质，不同于T307-c1先说陀罗再称其为杀星。"
  },
  {
   "编号": "T794-c3",
   "项": "问D",
   "裁定": "是",
   "依据": "",
   "理由": "原文不止说落陷就偏，还加了「不成正格了」「不成正那就不正了」两层，解释了为什么落陷会变成偏。"
  },
  {
   "编号": "T902-c2",
   "项": "C1",
   "裁定": "是",
   "依据": "武官星代表外刚",
   "理由": "原文先立「武官星」这一人物形象，再由武官这个人物推出外刚，属先说出星是什么人物再由人物推结论。"
  },
  {
   "编号": "T1113-c1",
   "项": "C2",
   "裁定": "是",
   "依据": "疾厄代表身体",
   "理由": "原文明说疾厄宫所主之事是身体，并以此推出最凶在身体，是把所主之事当理由。"
  },
  {
   "编号": "T1481-c2",
   "项": "问D",
   "裁定": "否",
   "依据": "",
   "理由": "「自己把自己书成偏房」「个性使然」只是重申个性导致偏房这一理由本身，没有再解释为什么「偏不要」会进偏房。"
  }
 ]
}

{
 "批": "N08",
 "裁定": [
  {
   "编号": "T12-c1",
   "项": "C4",
   "裁定": "否",
   "依据": "",
   "理由": "原话「她22生意太好了」里的「22」只是交代结论发生在哪个时段，原话没有把这个时机当作得出「生意太好」的理由来讲（「因为」是引向下一步「诸事皆吉」的），按 codebook 只说条件就有结论者为直断，故 C4 答否。"
  },
  {
   "编号": "T12-c2",
   "项": "问D",
   "裁定": "否",
   "依据": "",
   "理由": "原话把「太好了以后，包括所有的事情通通来了」当作理由（即 C5 一环），其后「所有的心里想的事情，她都会很顺心的能够达成」只是换一种说法重述「诸事皆吉」的结论，并没有再解释为什么生意好就会诸事皆吉，故问D 答否。"
  },
  {
   "编号": "T75-c1",
   "项": "C1",
   "裁定": "否",
   "依据": "",
   "理由": "「已经没有太阳了」本身就是这一步的结论，原话把它当作理由讲的只有「34岁以后」这个时机（C4 两人已同答是），并没有先立一个形象再由形象推出结论，形象不能既是结论又作依据，故 C1 答否。"
  },
  {
   "编号": "T156-c7",
   "项": "C1",
   "裁定": "是",
   "依据": "那个桃花那不贪狼廉贞嘛",
   "理由": "眯眯眼紧接「那个桃花那不贪狼廉贞嘛」，是先说出贪狼廉贞是桃花（星）再由此推出眯眯眼；按 codebook「桃花」属具体物象（问B 举例及「花」字之例，两人在 T156-c9/c10 也同判象名），所以这一环归象，C1 答是。"
  },
  {
   "编号": "T156-c7",
   "项": "C2",
   "裁定": "否",
   "依据": "",
   "理由": "原话拿来当理由的只有「桃花」这一个名目，而「桃花」按 codebook 是物象而非抽象性质、德性，与问B 象名／义名之分相应，象的一环已归 C1，不再重复记为义，故 C2 答否。"
  },
  {
   "编号": "T156-c8",
   "项": "C1",
   "裁定": "是",
   "依据": "那个桃花那不贪狼廉贞嘛",
   "理由": "与 T156-c7 同一句原话、同一推法，廉贞被说成桃花（星）再由此推出眯眯眼，「桃花」为物象，故 C1 答是。"
  },
  {
   "编号": "T156-c8",
   "项": "C2",
   "裁定": "否",
